SELECT * FROM t_zgsq_op_log
WHERE 1 = 1

    AND op_module LIKE CONCAT('%', #{opModule}, '%')


    AND op_user_name LIKE CONCAT('%', #{opUserName}, '%')


    AND op_time >= #{startTime}


    AND op_time <= #{endTime}

ORDER BY op_time DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM t_zgsq_op_log
WHERE 1 = 1

    AND op_module LIKE CONCAT('%', #{opModule}, '%')


    AND op_user_name LIKE CONCAT('%', #{opUserName}, '%')


    AND op_time >= #{startTime}


    AND op_time <= #{endTime}
